const fs = require('node:fs');
const path = require('node:path');
const records = JSON.parse(fs.readFileSync(path.join(__dirname,'records.initial.json')));
const docs = {
  ar:'https://guides.rubyonrails.org/active_record_basics.html',
  assoc:'https://guides.rubyonrails.org/association_basics.html',
  callbacks:'https://guides.rubyonrails.org/active_record_callbacks.html',
  query:'https://guides.rubyonrails.org/active_record_querying.html',
  migration:'https://guides.rubyonrails.org/active_record_migrations.html',
  controller:'https://guides.rubyonrails.org/action_controller_overview.html',
  assets:'https://guides.rubyonrails.org/asset_pipeline.html',
  security:'https://guides.rubyonrails.org/security.html',
  jobs:'https://guides.rubyonrails.org/active_job_basics.html',
  ruby:'https://docs.ruby-lang.org/en/master/',
};
// These authored clarifications override misleading source explanations. Original text stays in sourceAnswer.
const entries = [
[/Active.?storage|file uploads/i,'Active Storage attaches files to Active Record models and delegates storage to a configured service, such as local disk or S3.', 'Install its tables, configure the storage service, declare has_one_attached or has_many_attached, and authorize upload/download operations. Image variants use an image processor such as libvips. Validate size and actual content, and use safe serving/scanning policies. Rails 8.1 removed the built-in Azure service; older lists of supported services need version context.', 'bin/rails active_storage:install\nbin/rails db:migrate\n# In User: has_one_attached :avatar\nuser.avatar.attach(io: File.open("avatar.png"), filename: "avatar.png")\nuser.avatar.variant(resize_to_limit: [100, 100])', ['Signed blob URLs are not a complete application authorization policy.','Direct uploads still require server-side validation and cleanup of unattached blobs.'], 'https://guides.rubyonrails.org/v8.1/active_storage_overview.html'],
[/\bConcerns\b/i,'A Rails concern is a module used to share a cohesive behavior; ActiveSupport::Concern adds inclusion hooks and class-method support.', 'Place model or controller concerns in their conventional directories. Use included for declarations needed on the including class, class_methods for class-level behavior, and instance methods for record/controller behavior. Concerns can reduce duplication, but a module that depends on many hidden methods can increase coupling.', 'module Publishable\n  extend ActiveSupport::Concern\n  included do\n    scope :published, -> { where(published: true) }\n  end\n  def publish!\n    update!(published: true)\n  end\nend\n# class Article < ApplicationRecord; include Publishable; end', ['Ruby keywords are lowercase; the source’s End does not close a definition.'], 'https://api.rubyonrails.org/classes/ActiveSupport/Concern.html'],
[/puts and print/i,'puts prints values with line endings, while print writes values without automatically appending a newline. Ruby blocks are closures passed to methods for caller-defined behavior.', 'puts handles arrays by printing their elements recursively and avoids adding a second newline when a string already ends with one. print uses object string representations. Methods such as each and map invoke the supplied block, and a custom method can use yield.', 'print "A"\nprint "B"\nputs "C" # the line becomes ABC followed by a newline\np [1, 2].map { |n| n * 2 } # [2, 4]', ['puts and print normally return nil; p is different and is useful for inspecting values.'],docs.ruby],
[/Given two models, Author and Book/i,'Declare has_many :books on Author and belongs_to :author on Book; join authors when filtering books by an author’s name.', 'The books table needs author_id and normally an index and foreign key. Query from Book so the result is a relation of books. Names are not necessarily unique, so this returns books for all authors with that name unless the business schema defines uniqueness.', 'class Author < ApplicationRecord\n  has_many :books\nend\nclass Book < ApplicationRecord\n  belongs_to :author\nend\nBook.joins(:author).where(authors: { name: "Jane Doe" })', ['Use a stable author ID when the intention is one specific person.'],docs.assoc],
[/What is a Rails model|define a model/i,'A Rails model is a Ruby object representing domain data and behavior; a database-backed model normally inherits from ApplicationRecord.', 'Migrations define database columns and Rails exposes typed attribute methods from the schema. Models can declare validations, associations, scopes and domain operations. Non-persistent models can use Active Model, so the term model is broader than a database table.', 'class Product < ApplicationRecord\n  validates :name, presence: true\n  validates :price, numericality: { greater_than: 0 }\nend\n# products table: name:string, price:decimal', ['Use a decimal or integer minor units for money rather than a binary float.'],docs.ar],
[/purpose of a Rails controller|What is a Rails controller/i,'A controller coordinates an HTTP request: it reads parameters, enforces authentication/authorization, invokes application behavior and selects the response.', 'Routes dispatch requests to actions. A controller can render HTML, JSON or another representation, or redirect. Keep domain workflows in models/services where they can be reused and tested independently; a controller should not be the only location enforcing an invariant.', 'class ArticlesController < ApplicationController\n  def show\n    @article = Article.find(params[:id])\n  end\nend', ['Handle missing resources and object-level access according to the API/UI contract.'],docs.controller],
[/Rails view|views in Rails|display a variable from a controller/i,'A view turns data prepared for a response into a presentation, commonly HTML using ERB templates.', 'Controllers expose instance variables to their view context. ERB <%= ... %> outputs a value and <% ... %> executes Ruby without directly outputting its result. Presentation belongs here; permission decisions and domain invariants still need server-side enforcement.', '<%# app/views/articles/show.html.erb %>\n<h1><%= @article.title %></h1>', ['Normal ERB output is HTML-escaped; avoid html_safe for untrusted content.'],docs.controller],
[/rails new.*rails generate/i,'rails new creates an application; rails generate creates a component within an existing application.', 'The application generator establishes the project and dependency setup. Component generators create models, migrations, controllers, jobs, channels or scaffolds. Inspect generated code rather than treating it as finished business behavior.', 'rails new bookstore\ncd bookstore\nbin/rails generate model Book title:string\nbin/rails generate controller Books index show', ['Use bin/rails inside a project to use its bundled Rails.'], 'https://guides.rubyonrails.org/command_line.html'],
[/new controller.*command line/i,'Run bin/rails generate controller followed by a controller name and optional actions.', 'The generator creates controller-related files and action routes according to its templates. Use plural resource controller names conventionally, and explicitly configure resources when building RESTful CRUD routes; a list of generated actions alone does not imply correct HTTP verb handling.', 'bin/rails generate controller Books index show\n# config/routes.rb:\n# resources :books, only: [:index, :show]', ['Do not expose create/update/destroy as GET routes.'], 'https://guides.rubyonrails.org/command_line.html'],
[/Rails routes|role of the .routes.rb/i,'config/routes.rb maps HTTP methods and URL patterns to endpoint handlers and creates URL/path helpers.', 'Routes are matched in declaration order. Use resources for a conventional collection, resource for a singular resource, and namespaces for organization. Routing selects an endpoint; it does not replace authentication or authorization.', 'resources :articles\nget "/about", to: "pages#about"\n# bin/rails routes', ['A singular resource has no index action and normally no :id path segment.'], 'https://guides.rubyonrails.org/routing.html'],
[/RESTful routes/i,'resources maps a resource to conventional index, show, new, create, edit, update and destroy actions using appropriate HTTP methods.', 'GET reads or displays a form, POST creates, PATCH/PUT updates, and DELETE destroys. HTML forms use Rails helpers to represent verbs not directly supported by native forms. A singular resource omits the collection index and the member ID path segment.', 'resources :articles, only: [:index, :show, :create]\n# GET /articles -> index\n# GET /articles/:id -> show\n# POST /articles -> create', ['RESTful route conventions do not themselves make operations authorized or idempotent.'], 'https://guides.rubyonrails.org/routing.html'],
[/Rails form|form.*HTML|nested attributes/i,'Rails form helpers generate HTML tied to a URL or model; nested forms use fields_for with accepts_nested_attributes_for when updating associated records through a parent.', 'Use form_with for model binding and built-in form conventions. For nested updates, permit a deliberate attribute list and authorize the child records being changed. allow_destroy controls nested deletion through _destroy; include an ID when modifying an existing child.', '<%= form_with model: @user do |form| %>\n  <%= form.text_field :name %>\n  <%= form.fields_for :posts do |post| %>\n    <%= post.text_field :title %>\n  <% end %>\n<% end %>\n# params.require(:user).permit(:name, posts_attributes: [:id, :title])', ['Strong parameters filter mass assignment; they do not replace authorization or validation.'],docs.controller],
[/partial/i,'A partial is a reusable view template whose filename normally starts with an underscore.', 'Render a partial with explicit locals or use collection rendering. It improves composition and avoids duplicating presentation. Keep its dependencies clear so it can be reused without relying on many controller instance variables.', '<%= render "product", product: @product %>\n<%= render @products %>\n<%# _product.html.erb %>\n<%= product.name %>', ['A partial is not a layout or a controller action.'], 'https://guides.rubyonrails.org/layouts_and_rendering.html'],
[/debug a Rails application/i,'Reproduce the issue, inspect the backtrace and logs, and use a debugger to verify the state at the failing operation.', 'Modern generated CRuby Rails applications include the debug gem in development/test; binding.break or debugger enters it. Older sources may use byebug or pry. Correlate request IDs and external-service events, write a regression test, and keep interactive breakpoints out of live production traffic.', 'def show\n  @article = Article.find(params[:id])\n  binding.break # development debugging with debug loaded\nend', ['Never log secrets or full sensitive request bodies.'], 'https://guides.rubyonrails.org/debugging_rails_applications.html'],
[/flash.*message/i,'flash carries temporary values across the current and next request, commonly for a one-time notice after a redirect.', 'Use flash.now when rendering in the current request so the message does not linger into a following request; use flash.keep to preserve it for another request. Rendering does not itself perform the same request-cycle transition as redirecting.', 'redirect_to articles_path, notice: "Saved"\n# On validation failure with a render:\nflash.now[:alert] = "Please fix the errors"', ['Flash lifetime follows requests, not the number of view templates rendered.'],docs.controller],
[/custom validator/i,'A custom validator adds validation errors according to a domain rule, using a model method, ActiveModel::EachValidator or ActiveModel::Validator.', 'Choose EachValidator for an attribute-oriented rule and Validator for a rule involving the record. Treat missing values explicitly. Rails applications should use Date.current for the configured application time zone rather than assuming the system date is correct.', 'class FutureDateValidator < ActiveModel::EachValidator\n  def validate_each(record, attribute, value)\n    if value.nil? || value <= Date.current\n      record.errors.add(attribute, "must be in the future")\n    end\n  end\nend\n# validates :expires_on, future_date: true', ['Combine a presence validator or explicit nil behavior with the business rule.'], 'https://guides.rubyonrails.org/active_record_validations.html'],
[/authentication and authorization|role.based access/i,'Authentication identifies the caller; authorization decides whether that caller may perform a specific operation on a specific resource.', 'Rails 8 has an authentication generator as a starting point; Devise is another established option with a different feature set. Use policies or abilities for authorization, scope queries to accessible records, and test cross-user access. A token format such as JWT is not a complete security design.', 'article = current_user.articles.find(params[:id])\n# With a policy library, authorize the requested action explicitly.\n# bin/rails generate authentication # Rails 8 starting point', ['UI visibility is not server-side access control.','Keep password hashing, session rotation and object access checks separate concerns.'],docs.security],
[/use of scopes/i,'A scope names a composable Active Record relation so repeated query intent stays readable.', 'Use a lambda for parameters and time-sensitive expressions, and return a relation so callers can chain it. Avoid hiding authorization in an optional scope. A default_scope applies implicitly and needs special care because unscoped or alternative access paths can bypass it.', 'class Article < ApplicationRecord\n  scope :published, -> { where(published: true) }\n  scope :recent, -> { order(created_at: :desc) }\nend\nArticle.published.recent.limit(20)', ['Inspect generated SQL; a readable scope can still issue an expensive query.'],docs.query],
[/naming convention/i,'Rails conventionally maps a singular CamelCase model such as BookClub to a plural snake_case table such as book_clubs; controller classes usually use plural CamelCase names.', 'Methods, variables, and filenames use snake_case. Constants and class/module names begin with an uppercase letter. These are conventions, not universal restrictions: irregular inflections and explicit table names are supported. Zeitwerk expects the file path to match the constant it defines.', 'class BookClub < ApplicationRecord\nend\n# app/models/book_club.rb; table: book_clubs\n# BookClubsController: app/controllers/book_clubs_controller.rb', ['The correct paths are app/controllers and app/helpers.','Keep the model/table convention separate from association naming.'], docs.ar],
[/\bORM\b|What is ActiveRecord|What is Active Record|What does it help us do/i,'Active Record is Rails’ Object-Relational Mapping layer: model classes usually represent tables, instances represent rows, and attributes represent columns.', 'It supplies query relations, persistence, type casting, associations, validations, callbacks, and migrations. It does not remove the need to understand SQL, indexes, transaction boundaries, or database constraints. Model objects can also be non-persistent Active Model objects, so not every Rails model must map to a table.', 'class User < ApplicationRecord\n  validates :email, presence: true\nend\nUser.where(active: true).order(:id).limit(20)', ['ORM means Object-Relational Mapping, not Object Relationship Model.','Application validations alone cannot enforce uniqueness under concurrency.'], docs.ar],
[/false and nil/i,'false is the sole instance of FalseClass and represents a false boolean value; nil is the sole instance of NilClass and normally represents absence. Both are falsey.', 'Only false and nil are falsey in Ruby. Zero, an empty string, and an empty array are truthy. Distinguish an absent value from an explicit false setting, especially when applying defaults. In Rails, false.blank? is true, so a presence validation is unsuitable for requiring a boolean to be either true or false.', 'p [false.class, nil.class] # [FalseClass, NilClass]\np !!0                     # true\nvalue = false\np value.nil? ? :missing : value # false', ['Use inclusion: { in: [true, false] } for a required boolean.'], docs.ruby],
[/String and Symbol/i,'A String represents text and is usually mutable; a Symbol is an immutable, interned identifier.', 'Repeated creation of the same symbol returns the same Symbol object. Strings may be frozen or deduplicated depending on how they are created. Dynamically created symbols have been eligible for collection in modern Ruby; the old blanket claim that symbols are never garbage-collected is outdated. Choose symbols for identifiers and strings for user content.', 'p :status.equal?(:status) # true\ns = "open"\ns << "!"\np s # "open!"', ['Do not claim every equal string always allocates separately.','Do not convert unlimited untrusted input into identifiers without considering resource usage.'], docs.ruby],
[/sub-directory app\/controller|purpose of Rails helpers|What are Helpers|role.*helper/i,'Controllers in app/controllers coordinate HTTP requests; helper modules in app/helpers provide reusable presentation methods for views.', 'A controller action loads or changes application state, enforces authorization, and chooses a response. Helpers format or construct view content. They are not a substitute for domain services or authorization policies; controller access to helpers is not automatic in every calling context.', 'module UsersHelper\n  def display_name(user)\n    user.name.presence || "Anonymous"\n  end\nend', ['Both directory names are plural.','Keep database-heavy business logic out of view helpers.'],docs.controller],
[/Migration|self.up and self.down|common data types.*migration/i,'Rails migrations are versioned Ruby classes that change database structure; bin/rails db:migrate applies pending versions and bin/rails db:rollback reverts the most recent reversible migration.', 'Use change for operations Rails can reverse, or explicit up/down or reversible for operations needing an inverse. Rails records applied versions in schema_migrations; migrations are not required to be arbitrarily rerunnable. A rollback does not recreate deleted production data. Database adapters differ in DDL transactions, locking, types, and supported index operations.', 'class AddEmailIndex < ActiveRecord::Migration[8.0]\n  def change\n    add_index :users, :email, unique: true\n  end\nend\n# bin/rails db:migrate\n# bin/rails db:rollback STEP=1', ['Use the migration compatibility version generated for the application.','A references column and an actual foreign key constraint are different; request foreign_key: true.','For large changes use expand/backfill/contract and database-appropriate locking precautions.','Modern migrations use instance methods def up / def down; self.up / self.down are legacy syntax.'],docs.migration],
[/Mixin|Multiple Inheritance/i,'Ruby classes have one superclass, but can compose behavior from multiple modules using include, prepend, or extend.', 'include adds a module’s instance methods to an ancestor chain; prepend places them before the class; extend adds them to one object’s singleton class. Lookup order resolves conflicts, and super continues through that chain. A module supplies behavior and namespaces but cannot be instantiated with ModuleName.new.', 'module Named\n  def label = "user"\nend\nclass User\n  include Named\nend\np User.new.label # "user"', ['Mixin composition is not multiple class inheritance.','Use ancestors and singleton_class.ancestors to explain lookup order.'],docs.ruby],
[/variable.*Global|Instance variable, Global|How to define the Instance/i,'Instance variables use @name, class variables use @@name, and global variables use $name. Ordinary local variables have no prefix.', 'Instance variables belong to a particular object, including class objects. Class variables are shared within a class hierarchy and can lead to surprising coupling. A class instance variable belongs to the class object and is distinct from a class variable. Local-variable scopes are lexical; blocks can capture surrounding local bindings.', 'class Counter\n  @total = 0 # class instance variable\n  def initialize\n    @value = 0 # each Counter instance owns this\n  end\nend', ['Prefer explicit dependencies over mutable global state.'], docs.ruby],
[/types of Association|types of association|Association relationships|association.*has_many/i,'Rails associations describe object relationships: belongs_to, has_one, has_many, has_many :through, has_one :through, and has_and_belongs_to_many.', 'belongs_to declares the foreign-key-owning side; it does not on its own make the database relationship one-to-one. Pair it with has_many for many children per parent, or has_one plus a unique foreign-key index for one-to-one. Ordinary foreign keys and uniqueness constraints enforce integrity independently of Rails validations.', 'class Author < ApplicationRecord\n  has_many :books\nend\nclass Book < ApplicationRecord\n  belongs_to :author\nend\nBook.joins(:author).where(authors: { name: "Jane Doe" })', ['Deleting a parent does not automatically delete children unless dependent behavior or database constraints require it.','Decide on nullability, foreign keys, indexes and dependent behavior explicitly.'],docs.assoc],
[/has_many :through and has_and_belongs_to_many/i,'Use has_and_belongs_to_many for a simple many-to-many join table; use has_many :through when the relationship needs its own model, behavior, validations, or extra data.', 'Both need a database join structure. HABTM does not automatically create the table from model declarations; use a migration. With a join model, treat membership itself as an entity, such as Enrollment holding joined_at or status. A uniqueness index can prevent duplicate memberships.', 'class Enrollment < ApplicationRecord\n  belongs_to :student\n  belongs_to :course\nend\nclass Student < ApplicationRecord\n  has_many :enrollments\n  has_many :courses, through: :enrollments\nend', ['Neither association is universally better.'],docs.assoc],
[/Scaffolding/i,'A Rails scaffold generator creates an initial model, migration, controller, views, routes, and tests for resource CRUD.', 'It accelerates an application’s first implementation, but generated code still needs authorization, domain validation, accessible views, security review, and meaningful tests. The generated files vary with Rails version and installed generators.', 'bin/rails generate scaffold Article title:string body:text\nbin/rails db:migrate', ['Inspect generated routes and permitted parameters before exposing CRUD.'],docs.controller],
[/default environments|Rails environments|different environments/i,'Rails normally has development, test, and production environments, selected by RAILS_ENV and configured under config/environments.', 'Separate database configuration, credentials and external service endpoints per environment. Development favors reloading and useful diagnostics; test runs controlled automated checks; production favors efficient stable serving. Isolation and backups are operational choices, not automatic guarantees simply because an environment is named production.', 'RAILS_ENV=production bin/rails runner \'puts Rails.env\'\n# config/environments/production.rb\n# config/database.yml', ['Do not run destructive maintenance against the wrong environment.'],docs.controller],
[/three components|\bMVC\b|flow of a request/i,'MVC separates domain data and rules in models, presentation in views, and HTTP coordination in controllers.', 'A request passes through Rack middleware and routing to a controller action. The controller authorizes the operation, invokes models or services, and renders a response, often using a view. Database-backed models use Active Record, while JSON APIs may render without an HTML view. Keep domain operations reusable outside controllers.', '# config/routes.rb\nresources :articles, only: :show\n# ArticlesController#show\n@article = Article.find(params[:id])\n# app/views/articles/show.html.erb\n# <%= @article.title %>', ['A real project example should describe your own work; source anecdotes are illustrative only.'],docs.controller],
[/Gemfile|install gems/i,'Gemfile declares dependencies and version constraints; Bundler resolves them, and Gemfile.lock records the exact resolved versions.', 'Add a gem to Gemfile and run bundle install. Commit the lockfile for an application to make installs reproducible. bundle update deliberately changes resolved versions; prefer a targeted update when that is the intention. A Gemfile alone does not pin every transitive version.', 'gem "bcrypt", "~> 3.1"\n# bundle install\n# bundle update bcrypt', ['Review compatibility, security advisories and the resulting lockfile diff.'],docs.ruby],
[/Garbage Collection/i,'Ruby’s garbage collector reclaims managed objects that can no longer be reached; this is a Ruby runtime feature, not a Rails-specific subsystem.', 'CRuby uses a tracing, generational, incremental collector and also supports heap compaction. Other implementations differ. Objects retained by global collections or caches remain reachable and cannot be reclaimed. Garbage collection does not reliably release external resources immediately.', 'before = GC.stat(:total_allocated_objects)\nitems = Array.new(1_000) { Object.new }\np GC.stat(:total_allocated_objects) - before\n# Use block-form File.open for deterministic file closing.', ['Do not use object counts alone as a diagnosis of resident memory.'],docs.ruby],
[/Class Library/i,'Ruby provides built-in core classes, standard libraries, default or bundled gems, and installable third-party gems.', 'Array, String, Hash and Thread are core examples. Libraries such as json and net/http provide reusable facilities and may be delivered as gems depending on Ruby release. GUI toolkits are not a universal built-in Ruby facility; choose an external library when required.', 'require "json"\np JSON.parse(\'{"name":"Ada"}\')["name"] # "Ada"', ['Check the target Ruby’s library packaging rather than assuming every historical standard library is installed.'],docs.ruby],
[/DRY code/i,'DRY means keeping each piece of knowledge or business rule in one authoritative place.', 'It reduces the risk that repeated rules drift apart. Extract a shared abstraction when the behavior represents the same underlying concept. Similar-looking code with different reasons to change may be clearer when kept separate.', 'def total_with_tax(net, rate:)\n  net * (1 + rate)\nend', ['Avoid premature abstractions that require many boolean options.'],docs.ruby],
[/benefits of using Ruby on Rails|What is Rails\?|What is Ruby on Rails/i,'Rails is a Ruby web application framework with conventions for routing, MVC, database access, views, jobs and other common application needs.', 'Convention over configuration provides sensible defaults; DRY encourages shared rules. These can speed development when the application fits the framework. Performance, security and scalability depend on implementation and operations, so the framework does not guarantee them. Domain models may use Active Record or ordinary Ruby objects.', 'bin/rails new bookstore\ncd bookstore\nbin/rails generate model Book title:string\nbin/rails db:migrate', ['Benchmark real workloads and understand generated code.'],docs.ar],
[/Nested Layout/i,'Nested layouts let a section-specific layout supply content inside the application layout.', 'Use content_for and a layout render to share the global shell while customizing an admin area or similar section. Layouts are composed templates; an ERB layout does not inherit like a Ruby class.', '<%# layouts/admin.html.erb %>\n<% content_for :content do %>\n  <aside>Admin</aside><%= yield %>\n<% end %>\n<%= render template: "layouts/application" %>\n<%# application: yield(:content).presence || yield %>', ['Avoid naming a content block ambiguously or recursively rendering the same layout.'],docs.controller],
[/Load and Require/i,'load executes a Ruby file every time; require loads a feature only when it has not already been required.', 'require resolves features using the load path and records them in $LOADED_FEATURES. require_relative resolves relative to the current file. load accepts a path and can execute within an anonymous module when wrapping is requested. Repeated load can redefine methods and rerun side effects.', 'require "json"           # true first time, false thereafter\nrequire_relative "rules" # rules.rb beside this source file\nload "./config_task.rb"  # executed each time', ['require does not simply paste a file’s text into lexical scope.'],docs.ruby],
[/what Delete does/i,'delete removes an Active Record row directly without model destruction callbacks; delete_all performs a relation-level bulk DELETE.', 'Deletion still obeys database constraints and database triggers. It bypasses model-level dependent destruction logic. Use destroy when destruction callbacks or dependent association actions are needed, and choose bulk deletion deliberately for large datasets.', 'user = User.find(1)\nuser.delete\nUser.where(inactive: true).delete_all', ['destroy runs destruction callbacks, not normal model validations.','A transaction can roll back a database deletion before it commits.'],docs.callbacks],
[/what Destroy does/i,'destroy runs destruction callbacks and deletes a persisted record if the callbacks allow it; dependent association behavior follows its configuration.', 'A before_destroy callback can throw :abort, in which case destroy returns false; destroy! raises on a callback-aborted destruction. Existing database constraints still apply. Destroying a parent does not automatically destroy every child merely because has_many is declared.', 'class User < ApplicationRecord\n  has_many :posts, dependent: :destroy\n  before_destroy { throw :abort if admin? }\nend\nuser.destroy!', ['Normal save validations are not the protection used during destroy.','Database deletion inside a transaction is reversible until commit.'],docs.callbacks],
[/comments in Ruby/i,'Use # for a Ruby line comment; =begin and =end delimit a block comment when placed at the beginning of their lines.', 'Ruby ignores comments during execution. Explain intent and constraints rather than repeating the obvious code. A shebang and magic comments can have special interpreter effects, so their positions matter.', '# Prices are stored as integer cents.\nprice_cents = 1250', [],docs.ruby],
[/quotes for strings/i,'Double-quoted Ruby strings interpret interpolation and common escape sequences; single-quoted strings are mostly literal.', 'Single quotes still recognize escaped single quotes and backslashes. Both produce String objects and can be frozen. Prefer whichever clearly expresses the text; do not claim either is always faster in a meaningful application.', 'name = "Ada"\np "Hello #{name}" # "Hello Ada"\np \'Hello #{name}\' # "Hello \#{name}"', [],docs.ruby],
[/Gems and Gemset/i,'A gem is a packaged Ruby library; a gemset is an isolated collection of installed gems supported by tools such as RVM.', 'RubyGems distributes packages. Bundler uses Gemfile and Gemfile.lock to resolve and activate dependencies for a project, often making a separate gemset unnecessary. A gemset is a tool-specific environment mechanism, not a Rails model or built-in Ruby namespace.', 'gem install bundler\nbundle install\nbundle exec ruby app.rb', ['Do not confuse Gemfile groups with RVM gemsets.'],docs.ruby],
[/What are Filters|before_action filter/i,'Controller callbacks run before, around, or after actions; current APIs are before_action, around_action and after_action.', 'Use before_action for authentication or loading shared resources, and around_action for logic that wraps the action and yields. Rendering or redirecting from a before callback halts the remaining action chain, but does not automatically stop Ruby statements within that same method. Use return where needed.', 'before_action :require_login\nprivate\ndef require_login\n  return if current_user\n  redirect_to login_path\nend', ['before_filter and related filter names are historical APIs.'],docs.controller],
[/Render and Redirect|render.*redirect_to|redirect_to.*render/i,'render creates a response within the current request; redirect_to sends a redirect so the client makes a new request.', 'Rendering a template does not execute the other action or initialize its instance variables. Redirecting does not transfer local state except through mechanisms such as flash or parameters. Neither method is a Ruby return statement. After a successful modifying form submission, a 303 redirect is often appropriate.', 'if @article.update(article_params)\n  redirect_to @article, status: :see_other\nelse\n  render :edit, status: :unprocessable_entity\nend', ['Do not render twice or continue into another response.'],docs.controller],
[/After_save and After_commit/i,'after_save runs after a create/update save within its surrounding transaction; after_commit runs only when that transaction has committed, including configured destroy events.', 'The distinction is transaction timing, not just which operations trigger them. Work in after_save can still be rolled back by a later error. after_commit observes committed data, but its own failure cannot undo the commit. External side effects need retries or an outbox if delivery must be reliable.', 'class Order < ApplicationRecord\n  after_create_commit :enqueue_receipt\n  def enqueue_receipt\n    ReceiptJob.perform_later(id)\n  end\nend', ['after_commit does not make an external API and database update atomic.'],docs.callbacks],
[/types of Callbacks|What is Callback/i,'Active Record callbacks hook into validation, saving, creation, updating, destruction and loading; transaction callbacks run after commit or rollback.', 'Create and update save flows validate, run before/around save callbacks, then operation-specific callbacks, followed by after_save. Destroy has its own callback chain. around callbacks wrap their operation and must yield. after_find and after_initialize cover loading/instantiation. Bulk APIs can bypass callback chains.', 'class Post < ApplicationRecord\n  before_validation :normalize_title\n  after_create_commit :announce\n  private\n  def normalize_title = self.title = title.to_s.strip\n  def announce = AnnouncementJob.perform_later(id)\nend', ['Use throw :abort to halt a before callback intentionally.','Avoid hiding large multi-step workflows in callbacks.'],docs.callbacks],
[/Skip Callback/i,'skip_callback changes a class’s registered callback chain; it is not a temporary switch for one record.', 'Changing callbacks during a request affects other instances and can race with concurrent requests. For an exceptional per-record path, define an explicit condition or a service operation instead. Bulk update/delete APIs bypass callbacks but also skip associated model safeguards.', 'class User < ApplicationRecord\n  attr_accessor :skip_notification\n  after_save :notify, unless: :skip_notification\n  def notify\n    NotificationJob.perform_later(id)\n  end\nend\nuser.skip_notification = true\nuser.save!', ['Do not mutate a shared callback registry to control one request.'], 'https://api.rubyonrails.org/classes/ActiveSupport/Callbacks/ClassMethods.html'],
[/Polymorphic Association/i,'A polymorphic belongs_to lets one association refer to different model types using a type column and an ID column.', 'For example, comments can belong to articles or photos. The pair identifies one target for each comment, not multiple simultaneous parents. A conventional foreign key cannot reference several target tables, so integrity and rename/migration behavior need special care.', 'class Comment < ApplicationRecord\n  belongs_to :commentable, polymorphic: true\nend\nclass Article < ApplicationRecord\n  has_many :comments, as: :commentable\nend\n# comments: commentable_type, commentable_id; index both together', ['Never trust arbitrary client-supplied model names for constant lookup.'],docs.assoc],
[/Accessor Methods/i,'attr_reader defines a getter, attr_writer a setter, and attr_accessor both for an instance variable.', 'These Ruby methods generate ordinary methods and do not themselves persist values. Active Record derives its own database attribute accessors; casually overriding them with attr_accessor can hide persistence behavior. A reader alone does not make the returned object immutable.', 'class Person\n  attr_accessor :name\n  def initialize(name) = @name = name\nend\nperson = Person.new("Ada")\nperson.name = "Grace"\np person.name', ['attr_writer alone does not define the getter.'],docs.ruby],
[/super and super\(\)/i,'Bare super forwards the current method’s arguments to the next implementation; super() sends no positional or keyword arguments.', 'The next implementation may live in a prepended or included module, not only a superclass. An incoming block is normally forwarded by both forms; use &nil when it must not be forwarded. Explicit super(value) passes only the supplied argument list.', 'class Parent\n  def call(*args) = args\nend\nclass Child < Parent\n  def call(value)\n    [super, super()]\n  end\nend\np Child.new.call(7) # [[7], []]', ['Wrong arity is possible if the next method expects different arguments.'],docs.ruby],
[/Hash in Ruby/i,'A Ruby Hash stores key/value associations and preserves insertion order.', 'Hash keys are compared using hash and eql?, so keys need stable behavior while stored. Values can be any object. A missing key normally returns nil unless a default or default proc is configured; fetch can distinguish a missing key from a present nil.', 'counts = Hash.new(0)\n%w[ruby rails ruby].each { |word| counts[word] += 1 }\np counts # {"ruby"=>2, "rails"=>1}', ['Hash.new([]) shares one mutable default array; use a block for independent collections.'],docs.ruby],
[/Array#each and Array#map/i,'each executes a block for each element and normally returns its receiver; map collects block results into a new array.', 'Use each for side effects and map for transformations. Neither method itself replaces receiver elements, but the block can mutate referenced objects or the receiver. Without a block, these methods return an Enumerator. map! replaces elements in place.', 'numbers = [1, 2, 3]\np numbers.map { |n| n * 2 } # [2, 4, 6]\np numbers.each { |n| n * 2 } # [1, 2, 3]', ['Returning a new array is not deep copying the objects inside it.'],docs.ruby],
[/What is Yield/i,'yield invokes the block passed to the current Ruby method and supplies any arguments written after yield.', 'It is Ruby syntax, not a Rails-only method. Calling yield without a supplied block raises LocalJumpError unless guarded with block_given?. The block retains its lexical local-variable environment. Rails layouts also use yield to insert view content.', 'def twice\n  yield 1\n  yield 2\nend\ntwice { |n| puts n * 10 } # prints 10, then 20', ['A captured block can be named using &block and invoked with block.call.'],docs.ruby],
[/Clouser|closure/i,'A closure is executable code that retains access to the lexical bindings from where it was defined; Ruby blocks, Procs, and lambdas provide this behavior.', 'The closure captures bindings, not a frozen copy of each variable value. A retained binding can keep objects alive. Lambdas and non-lambda Procs differ in return behavior and argument checking even though both are Proc objects.', 'def counter\n  n = 0\n  -> { n += 1 }\nend\nc = counter\np [c.call, c.call] # [1, 2]', ['A method defined with def does not close over surrounding local variables like a block.'],docs.ruby],
[/Ruby different from Python/i,'Ruby and Python are dynamic object-oriented languages; their syntax, object models, block conventions, method lookup and ecosystems differ.', 'Ruby commonly uses end-delimited blocks, implicit method returns, symbols and mixins, with single class inheritance. Python uses indentation, explicit return, and supports multiple class inheritance. Both support functions expressed in their own language models and anonymous callables; Python also has match/case since 3.10. The source’s IDE, community and “not object-oriented” claims are misleading.', 'Ruby: [1, 2, 3].map { |n| n * 2 }\nPython: [n * 2 for n in [1, 2, 3]]', ['Python classes can act as mixins; claiming mixins are impossible is incorrect.','Ruby uses elsif, not elseif.','Python yield creates a generator; Ruby yield calls the method’s supplied block.'], 'https://docs.python.org/3/tutorial/classes.html'],
[/asset pipeline|add CSS and JavaScript/i,'An asset pipeline manages static asset discovery and fingerprinted URLs; exact bundling and preprocessing behavior depends on the configured tools and Rails version.', 'Rails 8 uses Propshaft by default. Propshaft does not itself perform general-purpose JavaScript/CSS bundling or minification; specialized tools can be added. Sprockets and Webpacker descriptions in older answers must be read in their historical context.', '<%= stylesheet_link_tag "application", "data-turbo-track": "reload" %>\n<%= javascript_importmap_tags %>\n# bin/rails assets:precompile', ['Webpacker is not the universal modern Rails default.','Do not assume every application concatenates all assets into exactly two files.'],docs.assets],
[/GET.*POST|POST.*GET/i,'GET requests retrieve representations and are defined to be safe and idempotent; POST asks the target resource to process content and is not generally idempotent.', 'The important distinction is HTTP semantics, not merely where parameters appear. GET can use query parameters; POST can have both a query string and request body. A POST body is not encrypted by being absent from the address bar: use HTTPS. Server, proxy and application limits still bound request sizes.', 'GET /articles?page=2\nPOST /articles\nContent-Type: application/json\n\n{"title":"Ruby"}', ['Do not implement state-changing actions with GET.','Never claim POST has no data-size limit or provides secrecy on its own.'],'https://www.rfc-editor.org/rfc/rfc9110.html'],
[/sessions and cookies/i,'Cookies store browser data; Rails sessions expose per-client state through a configurable store. Rails’ default CookieStore keeps encrypted and authenticated session data in the cookie.', 'Server-backed session stores usually keep only a lookup identifier in the browser. CookieStore does not require sticky sessions or a shared session database, but all app instances need compatible secrets. Keep sessions small, rotate them when authentication changes, and understand expiry and revocation requirements.', 'session[:user_id] = user.id\ncookies.encrypted[:preference] = { value: "dark", httponly: true }\nreset_session # for an authentication boundary', ['Do not claim Rails sessions are server-side by default.'],docs.controller],
[/start a Rails server/i,'Run bin/rails server (or bin/rails s) in the application directory; modern generated applications normally use Puma.', 'The development default port is usually 3000; override it with -p. bin/rails uses the application’s bundled Rails version. Production requires appropriate process supervision, networking, secrets and database configuration.', 'bin/rails server -p 4000\n# Open http://localhost:4000', ['WEBrick as the default is historical, not a general statement about current Rails.'], 'https://guides.rubyonrails.org/command_line.html'],
[/rails console/i,'bin/rails console loads an interactive Ruby session with the application environment, so you can query models and inspect behavior.', 'The normal console can persist database changes. The --sandbox option wraps database work in a transaction that rolls back on exit, but it does not undo emails, file writes or external calls. Use explicit limits when exploring large datasets.', 'bin/rails console --sandbox\nUser.where(active: true).limit(5).pluck(:id, :email)', ['A regular console is not an isolated security sandbox.'], 'https://guides.rubyonrails.org/command_line.html'],
[/CRUD|Create, Read, Update, Delete/i,'CRUD means Create, Read, Update and Delete; Active Record exposes these through persistence and query methods.', 'Use create!/save! and update! when validation failures should raise, and inspect errors when using non-bang methods. find raises for a missing ID; find_by can return nil. destroy runs destruction callbacks; delete bypasses them. Database constraints remain essential.', 'user = User.create!(name: "Ada", email: "ada@example.test")\nuser = User.find(user.id)\nuser.update!(name: "Grace")\nuser.destroy!', ['The source’s User.query and db.session snippets are Python/SQLAlchemy, not Rails.'],docs.ar],
[/eager loading/i,'Eager loading retrieves associations in a bounded set of queries before iteration to prevent N+1 database round trips.', 'preload fetches associations separately; eager_load uses a LEFT OUTER JOIN; includes chooses an approach based on relation conditions and references. Joining alone does not necessarily populate association caches. Loading too much data can increase memory, so select a strategy based on the access pattern.', 'authors = Author.preload(:books).limit(20)\nauthors.each { |author| puts author.books.size }', ['“Eager loading always means one query” is incorrect.'],docs.query],
[/internationalization|i18n|localization|l10n/i,'Use locale files and I18n.t for translations, and localization helpers for dates and numbers.', 'Choose a locale from an explicit allowlist and scope it to the request using I18n.with_locale. Setting thread-local locale without restoring it can leak state to another request on the same worker. Keep translation of interface strings separate from translation of stored user content.', 'around_action :with_locale\nprivate\ndef with_locale(&action)\n  locale = params[:locale].to_s.in?(%w[en fr]) ? params[:locale] : :en\n  I18n.with_locale(locale, &action)\nend', ['pluralize is not a complete translation strategy; use locale-specific pluralization keys.'], 'https://guides.rubyonrails.org/i18n.html'],
[/multi.tenancy/i,'Multi-tenancy can isolate customers by database, schema, or tenant-scoped rows; choose based on isolation, cost, operations and scale.', 'In a shared database, resolve the tenant from trusted authentication or host context, scope every access, include tenant IDs in relevant unique constraints, and test cross-tenant access. Background jobs and caches also need tenant context. A conditional default_scope that disappears when tenant context is missing fails open.', 'tenant = current_user.tenant\norder = tenant.orders.find(params[:id])\n# Composite uniqueness: add_index :orders, [:tenant_id, :number], unique: true', ['Do not put a tenant_id default scope on every ApplicationRecord table.','Consider database row-level security where appropriate, with correct connection/session handling.'],docs.security],
[/search functionality|complex search/i,'Build search with an authorized base relation, explicit filter and sort allowlists, bounded pagination, and indexes aligned with the search strategy.', 'Simple structured filters fit Active Record. PostgreSQL full-text search or an external search service may be suitable for ranked text search. Inspect query plans and deep-pagination behavior. Never pass arbitrary client input as an ORDER BY expression; advanced search libraries also need attribute and association allowlists.', 'sorts = { "newest" => { created_at: :desc }, "name" => { name: :asc } }\nrecords = current_user.tenant.products.where(active: true)\nrecords = records.order(sorts.fetch(params[:sort], sorts["newest"]))\nrecords = records.limit(25)', ['Keyset pagination can avoid expensive large offsets.','Escape LIKE wildcard characters when they should be literal.'],docs.query],
[/Sidekiq|background tasks|background jobs|What is Active Job|ActiveJob/i,'Active Job defines jobs and delegates execution to a queue adapter; Sidekiq is one backend, while current Rails also supports database-backed Solid Queue.', 'Enqueue durable work with perform_later and run workers for the chosen backend. Assume retries and possible repeated delivery: make effects idempotent. MRI threads help concurrent I/O; they do not guarantee parallel execution of CPU-bound Ruby code because of the GVL. Process-based workers can use multiple cores at additional memory cost.', 'class ReportJob < ApplicationJob\n  def perform(report_id)\n    report = Report.find(report_id)\n    return if report.completed?\n    # Generate report; guard durable effects against duplicate execution.\n  end\nend\nReportJob.perform_later(report.id)', ['A queue does not guarantee exactly-once processing.','Enqueue relative to transaction commit and handle deleted/deserialized records deliberately.'],docs.jobs],
[/caching|cache techniques/i,'Choose cache boundaries from measured expensive work, and define invalidation, key scope, expiry and failure behavior before adding a cache.', 'Fragment caching stores portions of rendered views; Russian doll caching nests fragments. Parent cache versions must change when relevant children change, often through touch: true. Low-level caching stores application data; HTTP caching uses validators or response headers. Page/action caching are historical extracted features, not simply built-in equivalents of all current caching.', '<% cache [current_user.role, @product] do %>\n  <%= render @product %>\n<% end %>\n# class Comment < ApplicationRecord\n#   belongs_to :article, touch: true\n# end', ['Include tenant/permission dimensions when results differ between users.','Avoid caching live Active Record instances; cache stable values or IDs where practical.'], 'https://guides.rubyonrails.org/caching_with_rails.html'],
[/payment gateway integration|processing payments/i,'Treat payment processing as a distributed workflow: the database and provider do not share one atomic transaction.', 'Compute amount and currency from a trusted server-side order, use the provider’s supported payment flow and idempotency mechanism, record state transitions, and verify webhook authenticity. Deduplicate webhook event IDs and tolerate out-of-order delivery. Do not hold a database lock across a slow network request when a state machine and idempotency can coordinate the workflow.', 'Order.transaction do\n  order.lock!\n  order.update!(payment_state: "pending")\n  # Persist a uniquely identified payment attempt / outbox event.\nend\n# A worker calls the provider using the persisted idempotency key.\n# A verified webhook applies an idempotent state transition.', ['The source’s client-supplied amount and legacy Stripe::Charge example should not be copied into production.','This is a conceptual workflow; provider-specific requests require its current documentation.'],docs.security],
[/securing.*CSRF|CSRF, XSS|web vulnerabilities/i,'Use CSRF protection for cookie-authenticated state changes, context-appropriate output escaping for XSS, and parameterized queries for SQL injection.', 'Rails provides helpful defaults, but application choices can bypass them. Avoid html_safe on untrusted text. Parameter binding is for values, so dynamic column names and sort directions need allowlists. Authentication does not replace object-level authorization; CORS is not CSRF protection.', 'User.where(email: params[:email])\n# ERB escapes user text by default:\n# <%= @comment.body %>\n# Allowlist dynamic ordering instead of interpolating SQL.', ['Use HTTPS and appropriate cookie flags.','Test authorization with another user’s record ID.'],docs.security],
[/Service Objects/i,'A service object is an ordinary Ruby object used to coordinate a business operation that does not fit cleanly in one controller or model method.', 'It can make a multi-step operation reusable and easier to test. This is an architectural pattern, not a special Rails subsystem. Define input, result and failure contracts; transactions cover only database work, so external effects need separate delivery guarantees.', 'class RegisterUser\n  def self.call(attributes)\n    user = User.create!(attributes)\n    WelcomeJob.perform_later(user.id)\n    user\n  end\nend', ['Use strong parameters at the HTTP boundary.','Do not mistake moving unsafe code into a service for making it atomic.'],docs.ar],
[/real.time|Action Cable|WebSockets/i,'Action Cable supplies Rails-integrated WebSocket connections and channels for server-to-client real-time events.', 'Authenticate the connection and authorize each subscription. Broadcast only data allowed for the specific stream audience. Multi-process deployments need a shared pub/sub adapter; configure the adapter for the application’s Rails version and infrastructure. Browser reconnection requires a plan for catching up missed events.', 'class NotificationsChannel < ApplicationCable::Channel\n  def subscribed\n    stream_for current_user\n  end\nend\nNotificationsChannel.broadcast_to(user, { message: "Report ready" })', ['Do not let a client select an arbitrary private user stream.'], 'https://guides.rubyonrails.org/action_cable_overview.html'],
[/\bRack\b/i,'Rack defines a common HTTP interface between Ruby application servers, middleware and frameworks.', 'A Rack application responds to call(env) with a status, response headers and response body. Middleware wraps that callable and can inspect or modify requests and responses. Follow the Rack version’s header, streaming and body-closing requirements.', 'app = ->(_env) { [200, { "content-type" => "text/plain" }, ["Hello"]] }', ['Rack is an interface/library, not the database layer.'], 'https://github.com/rack/rack/blob/main/SPEC.rdoc'],
[/ActiveModel::Serializers/i,'Serialization converts objects to an API representation; ActiveModel::Serializers is a separate gem, while Rails also exposes built-in serialization methods.', 'Specify an explicit response contract to avoid exposing secrets or internal fields. Choose built-in as_json/serializable_hash, a view builder, or a serializer library according to complexity. Authorization, association loading and version compatibility remain application responsibilities.', 'render json: user.as_json(only: [:id, :name])', ['Do not assume the ActiveModel::Serializers gem ships as a required Rails component.'],docs.ar],
[/Rake|rake.*task/i,'Rake tasks automate named operations; Rails exposes many built-in tasks through bin/rails.', 'Custom tasks belong in lib/tasks/*.rake. Depend on :environment when the task needs the application models. Make maintenance tasks resumable and safe for the selected environment. Modern route inspection uses bin/rails routes rather than assuming rake routes exists.', 'namespace :reports do\n  task refresh: :environment do\n    Report.find_each { |report| RefreshJob.perform_later(report.id) }\n  end\nend\n# bin/rails reports:refresh', ['Do not confuse db:reset with a safe incremental migration; it recreates the database.'], 'https://guides.rubyonrails.org/command_line.html'],
[/testing frameworks|testing in the context/i,'Rails includes Minitest support; RSpec is an alternative test framework. Choose tests that check meaningful behavior at suitable boundaries.', 'Use fast unit tests for business rules, request tests for HTTP contracts and authorization, integration tests for collaboration, and a smaller set of system tests for critical browser workflows. Request tests do not by themselves drive a browser. Isolate external services using controlled substitutes and test failure paths.', 'test "rejects a missing title" do\n  article = Article.new(title: nil)\n  assert_not article.valid?\n  assert_includes article.errors[:title], "can\'t be blank"\nend', ['Use your own experience when answering a behavioral interview prompt.'], 'https://guides.rubyonrails.org/testing.html'],
[/code reviews|code analysis tools/i,'Review behavior, security, performance and maintainability; use static tools to support human review.', 'Check requirements, authorization boundaries, failure handling, database constraints, query counts and tests. RuboCop flags style and selected code smells; Brakeman detects classes of Rails security problems. Neither proves correctness or reliably finds every insecure direct object reference or design violation.', 'bundle exec rubocop\nbundle exec brakeman\nbin/rails test', ['Prioritize defects and explain the impact of a review suggestion.'],docs.security],
[/legacy Rails|modernizing/i,'Stabilize a legacy application with tests and observability, then make small reversible upgrades and refactorings.', 'Identify business-critical paths and operational dependencies first. Add characterization tests, address security exposure, upgrade Ruby/Rails in supported steps, and remove deprecated APIs before crossing versions. Use feature flags or incremental replacement where a large rewrite would increase risk.', '# Typical loop:\n# reproduce -> characterization test -> small change -> full relevant checks\n# review deprecations -> deploy -> observe -> continue', ['Version upgrades need a tested compatibility plan, not just changing a Gemfile number.'], 'https://guides.rubyonrails.org/upgrading_ruby_on_rails.html'],
[/deploy.*production|deployment strategies/i,'Deploy a tested artifact with configured secrets, database access, asset handling, web/job processes, health checks and a rollback plan.', 'A release should apply compatible schema changes, start the correct processes, and verify readiness before sending traffic. Tools such as containers, Kamal or Capistrano automate different approaches. Zero-downtime changes need old and new application versions to tolerate the schema throughout rollout.', 'RAILS_ENV=production bin/rails assets:precompile\nRAILS_ENV=production bin/rails db:migrate\n# Start the configured Puma and worker processes via the deployment platform.', ['Precompile and migration placement vary by platform.','Rollback code cannot necessarily undo a destructive data migration.'], 'https://guides.rubyonrails.org/8_0_release_notes.html'],
[/optimize.*slow|slow.performing|performance monitoring/i,'Measure the bottleneck before changing the application: inspect latency distributions, traces, slow queries, allocation and queue metrics.', 'For database work, inspect actual SQL and query plans, fix N+1 patterns, and add indexes justified by query predicates and order. Consider bounded batches, less selected data, caching or background jobs only after understanding the workload. Re-measure the original case and watch regressions under representative concurrency.', 'users = User.preload(:posts).where(active: true).limit(100)\n# Inspect generated SQL and query plans for the database in use.\n# Compare p95 latency, query count and allocated bytes before/after.', ['An index adds write/storage cost and is not guaranteed to improve every query.','Choose alert thresholds from service objectives and avoid logging secrets.'],docs.query],
];
for (const r of records) {
  for (const [pattern, direct, explanation, example, points, url] of entries) {
    if (!pattern.test(r.question)) continue;
    r.directAnswer=direct; r.explanation=explanation; r.example=example; r.importantPoints=[...points,'Reference: '+url];
    if (r.sourceAnswer!==explanation) r.issues.push('Source explanation was expanded or corrected; use the interview answer above rather than copying the original passage.');
    break;
  }
  // All original MCQ options are retained. The chosen key below is derived, not present in the pasted source.
  if (r.sourceQuestionLabel.startsWith('MCQ-')) {
    const i=Number(r.sourceQuestionLabel.slice(4))-1;
    const keys=[2,2,2,2,3,2,2,2,3,2,2,2,2,3,2,3,1,1,2,2,2,2,1,2,3];
    const opts=r.sourceAnswer.split(/\n\s*\n/).map(s=>s.trim()).filter(s=>s&&!/^options:$/i.test(s));
    const key=keys[i];
    const chosen=opts[key-1];
    r.directAnswer='Option '+key+': '+chosen;
    if (!r.example) r.example='Decision example: '+chosen;
    if (r.explanation===r.sourceAnswer) r.explanation='The correct choice is '+chosen+' The other choices describe different Rails components or reverse the behavior being asked about.';
    r.issues.push('The pasted MCQ contains options but no answer key; this key is an independently derived answer.');
    if(i===1) {r.explanation='Option 2 is the historical Sprockets-era intended answer. For Rails 8 Propshaft, fingerprinting and serving browser-ready assets are core duties; general bundling/minification require separate tools.';r.issues.push('Version-qualified MCQ: its asset-pipeline option is outdated for default Propshaft applications.');}
    if(i===6)r.importantPoints.push('after_create is before the surrounding transaction commits; it is not after_create_commit.');
  }
  if(!r.example) {
    const exampleStart=r.sourceAnswer.search(/^(?:class |module |def |# |[A-Z]\w*\.(?:where|find|create)|bin\/rails|rails |<%=|GET |POST )/m);
    if(exampleStart>=0)r.example=r.sourceAnswer.slice(exampleStart).split(/\n\s*\n/)[0];
    else r.example=r.sourceAnswer;
  }
  if(/Describe your experience|Describe a time|challenging Rails project|stay up.to.date/i.test(r.question)) {
    r.issues.push('The source uses a first-person illustrative story. Do not present it as your own experience. Adapt the structure to a genuine project.');
    r.directAnswer='Use a real example from your work and explain the context, your responsibility, the concrete technical decision, the observed outcome, and the trade-off. '+r.directAnswer;
    r.importantPoints.push('A truthful project answer should include what you personally did and how the result was measured.');
  }
  if(/common data types/.test(r.question))r.importantPoints.push('JSON is not PostgreSQL-only; adapters including MySQL and SQLite offer differing JSON support. References default key size and foreign-key creation depend on explicit options and Rails configuration.');
  if(/flash/i.test(r.question))r.importantPoints.push('flash is normally available for the current and next request; use flash.now for a current render and flash.keep when preserving it further.');
  if(/Pundit|CanCanCan/.test(r.question))r.importantPoints.push('Use can?(:update, record) or a policy check; the source’s record.accessible_by? example is not a standard CanCanCan instance predicate.');
  const actualCorrections = {
    Q3:'The original expands ORM incorrectly; it means Object-Relational Mapping.',
    Q6:'Corrected singular directory names to app/controllers and app/helpers.',
    Q8:'Migrations do not guarantee adapter portability or reversibility of every operation.',
    Q12:'Distinguished three cardinalities from the six association declaration forms.',
    Q23:'Corrected load versus require: both execute code; require caches loaded features.',
    Q24:'Corrected the claim that destroy invokes normal validations; it invokes destruction callbacks.',
    Q28:'Qualified legacy filter names with current before_action/after_action/around_action APIs.',
    Q30:'Corrected malformed pasted Ruby and added a validation-failure status in the example.',
    Q31:'Qualified background job concurrency: job order/parallelism depend on backend and configuration.',
    Q32:'Corrected the missing transaction-timing distinction between after_save and after_commit.',
    Q33:'Corrected Sprockets-era pipeline behavior for the Rails 8 Propshaft default.',
    Q34:'Qualified callback coverage: delete and bulk methods can bypass lifecycle callbacks.',
    Q37:'Corrected the implication that declaring HABTM automatically creates its join table.',
    Q38:'Qualified Azure storage support: the built-in service was removed in Rails 8.1.',
    Q39:'Accessors are Ruby methods; Active Record column attributes are a separate mechanism.',
    Q40:'Corrected superclass-only wording: super follows the method ancestor chain.',
    Q41:'Corrected belongs_to as not inherently enforcing a one-to-one database relationship.',
    Q42:'Corrected skip_callback as class-wide registration mutation, not an instance-only temporary switch.',
    Q43:'Corrected uppercase End and broken pasted code in the concern example.',
    Q44:'Corrected unconditional cascading deletion, validations, and transaction irreversibility claims.',
    Q47:'Qualified the claim that each cannot mutate data: its block can mutate objects.',
    Q48:'Distinguished historical self.up/self.down from modern migration instance methods.',
    Q50:'Corrected closure terminology and explained binding capture rather than value snapshots.',
    Q51:'Corrected multiple Ruby/Python table claims: Python OOP, mixins, match/case, Ruby elsif, and IDE myths.',
  };
  if(r.sourceFile==='twentythree.txt'&&actualCorrections[r.sourceQuestionLabel])r.issues.push(actualCorrections[r.sourceQuestionLabel]);
}
fs.writeFileSync(path.join(__dirname,'records.json'),JSON.stringify(records,null,2));
fs.writeFileSync(path.join(__dirname,'review.md'),'# Root source review\n\nRead all 856 physical lines of twentythree.txt and 1324 of twentyseven.txt, revisiting truncated output in smaller ranges. Extracted 185 occurrences: 51 + 105 open questions + 25 MCQs + 4 embedded technical prompts. Original answer text is retained separately. Corrections distinguish modern tooling from historical behavior; missing MCQ keys are independently derived. Behavioral sample stories are not personal experience.\n');
console.log('Enriched',records.length,'records;',records.filter(r=>r.issues.length).length,'with notes');
